/// <summary>
///     The <c>AVACustTableFrm_CustTableDS_SalesTypeFld_Extension</c> class is the extension for <c>CustTable</c>
/// </summary>
[ExtensionOf(formDataFieldStr(CustTable, CustTable, KCS_TOSId))]
final class AVACustTableFrm_CustTableDS_KCS_TOSIdFld_Extension
{
}

Method.Source:
/// <summary>
///     AVA <c>modified</c> method.
///     AVA - Schneider 15.03.2024
/// </summary>
public void modified()
{
    FormDataSource  locFormDataSource;
    CustTable       locCustTable;
    KCS_TOSTable    locKCS_TOSTable;

    str             locDialogButtonTitle;
    str             locDialogButtonMessage;
    DialogButton    locDialogButton;

    next modified();

    locFormDataSource   = element.CustTable_DS;
    locCustTable        = locFormDataSource.cursor();

    if(     locCustTable.RecId 
        &&  locCustTable.KCS_TOSId  )
    {
        locKCS_TOSTable = KCS_TOSTable::find(locCustTable.KCS_TOSId);
        //if(locKCS_TOSTable.RecId &&  locKCS_TOSTable.AVAEmailInvoice)
        if(locKCS_TOSTable.RecId)
        {
            if(locCustTable.AVAEmailInvoice != locKCS_TOSTable.AVAEmailInvoice)
            {
                //Box
                locDialogButtonMessage  = strfmt("@NDX:NXAQuestionInvoiceEmailTOSP1CustomerP2TransferToTOS", locKCS_TOSTable.AVAEmailInvoice, locCustTable.AVAEmailInvoice);
                locDialogButtonTitle    = SysLabel::labelId2String("@NDX:NXATransferEmailInvoiceToCustomer");

                locDialogButton = Box::yesNo(   locDialogButtonMessage, 
                                                DialogButton::Yes, 
                                                locDialogButtonTitle    );
                if(locDialogButton == DialogButton::Yes)
                {
                    locCustTable.AVAEmailInvoice = locKCS_TOSTable.updateAVAEmailInvoiceToCustAccount(locCustTable.AccountNum);
                }
            }
        }
    }
}
